@pytest.mark.parametrize('outcome',['completed','partial','pending']) def test_batch_self_mutation_preserves_safe_execution_status_after_source_change_and_revocation(application,outcome): app=application;enable(app.host,public=True,private=True,kp=True) s=session(app);r=submit(app,s,'修改已读取的角色') request=app.repository.state()['requests'][r['requestId']] snapshot,_=Context(app.proposals,demand=True).capture('kp',request) queries=DataQueryService(app.host) page=queries.attach('kp','search',{'types':['entity'],'query':'','limit':50},snapshot,'kp') name=app.host.state()['entities']['actor-one']['name'] ref=next(i['ref'] for i in page['items'] if i['label']==name) queries.attach('kp','read',{'refs':[ref]},snapshot,'kp') actions=[{'target':'host','op':'entity.patch','args':{'id':'actor-one','name':'批次已修改'}}] bid=app.batches.create('kp',request,actions,'SECRET_ORIGINAL_SUMMARY',snapshot[0]) item=next(i for i in app.rulings.list('kp')['items'] if i['rulingId']=='batch:'+bid) assert item['status']=='pending' and item['canDecide'] args={'rulingId':item['rulingId'],'digest':item['digest'],'decision':'approve'} if outcome=='pending': receipt=app.rulings.host_command('kp','external-change','entity.patch',{'id':'actor-one','name':'其他修改'}) assert receipt['status']=='committed' else: result=committed(command(app,'ai.ruling.decide',args)) assert result['status']=='completed',result if outcome=='partial': # Seed a legacy sequential audit: one real committed mutation and a # historical rejection. New atomic batches cannot produce partial. def legacy(state): record=state['settings']['batches'][bid] record['context']['facts'].pop('batchExecutionVersion') record['actions'].append({'target':'host','op':'entity.patch','args':{'id':'missing-actor','name':'不应成功'}}) record['receipts'].append({'id':'legacy-failed','account':'kp','target':'host','receipt':{'status':'rejected','code':'NOT_VISIBLE'}}) record['status']='partial' for key in ('execution','preflight','executionCommandId','batchReceipt'):record.pop(key,None) record['digest']=digest({k:record[k] for k in ('batchId','sessionId','requestId','creator','actions','context','baseline','authorityEpoch')}) app.repository.update(legacy) expected={'completed':[{'receipt':{'status':'committed'}}], 'partial':[{'receipt':{'status':'committed'}},{'receipt':{'status':'rejected'}}],'pending':[]}[outcome] for revoked in (False,True): if revoked:enable(app.host,public=False,private=False,kp=False) view=next(i for i in app.rulings.list('kp')['items'] if i['rulingId']=='batch:'+bid) assert view['status']==outcome and view['canDecide'] is False > assert view['actions']==[] and view['receipts']==expected E AssertionError: assert ([{'target': '...e': '批次已修改'}}] == [] E E Left contains one more item: {'target': 'host', 'op': 'entity.patch', 'args': {'id': 'actor-one', 'name': '批次已修改'}} E Use -v to get more diff)
